// === Tab: mySketch ===
const N = 50;
const speed = 0.002;

let canvasSize;
let myShader;
let smokes = [];
let hue;
let mode;

const vert = `
attribute vec3 aPosition;
attribute vec3 aNormal;
attribute vec2 aTexCoord;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
uniform mat3 uNormalMatrix;

uniform vec3 uAmbientColor[5];
uniform vec3 uLightingDirection[5];
uniform vec3 uDirectionalDiffuseColors[5];

varying highp vec2 vVertTexCoord;
varying vec3 vAmbientColor;
varying vec3 vLightDirection;
varying vec3 vDirectionalColor;
varying vec3 vNormal;

void main(void) {
  vec4 viewModelPosition = uModelViewMatrix * vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * viewModelPosition;

	vNormal = normalize(uNormalMatrix * aNormal);
	vLightDirection = -uLightingDirection[0];
	vAmbientColor = uAmbientColor[0];
	vDirectionalColor = uDirectionalDiffuseColors[0];

  vVertTexCoord = aTexCoord;
}
`;


const frag = `
precision highp float;

uniform vec4 uMaterialColor;
uniform sampler2D uSampler;
uniform bool isTexture;

varying highp vec2 vVertTexCoord;
varying vec3 vAmbientColor;
varying vec3 vLightDirection;
varying vec3 vDirectionalColor;
varying vec3 vNormal;

void main(void) {
	vec3 direction = normalize(vLightDirection);
	vec3 normal = normalize(vNormal);
	float diffuse = max(0.0, dot(direction, normal));
	float value;
	if (diffuse > 0.8) {
		value = 1.0;
	} else if (diffuse > 0.5) {
		value = 0.8;
	} else if (diffuse > 0.1) {
		value = 0.5;
	} else {
		value = 0.1;
	}
	vec3 diffuseColor = vAmbientColor + value * vDirectionalColor;	

	vec2 v = gl_FragCoord.xy * 0.8;
	float f = (sin(v.x) * 0.5 + 0.5) + (sin(v.y) * 0.5 + 0.5);

	if(!isTexture) {
		gl_FragColor = max(uMaterialColor * vec4(vec3(max(diffuse + f, 0.9)) * diffuseColor, 1.0), vec4(vAmbientColor, 1.0));
		gl_FragColor = vec4(vec3(max(diffuse + f, 0.2)) * uMaterialColor.rgb * diffuseColor, 1.0);
		gl_FragColor = uMaterialColor;
		gl_FragColor.rgb = gl_FragColor.rgb * diffuseColor;
	}
	else {
		gl_FragColor = texture2D(uSampler, vVertTexCoord) * vec4(vec3(diffuse + f) * diffuseColor, 1.0);
	}
}
`;

function setup() {
	createCanvas(1112, 834, WEBGL);
	pixelDensity(1);
	canvasSize = max(width, height);
	myShader = createShader(vert, frag);
	shader(myShader);

	for (let i = 0; i < N; i++) {
		const life = random();
		const r = random();
		const angle = random(TWO_PI);

		smokes.push({life: life, r: r, angle: angle});
	}

	hue = int(random(36000) % 360);
	mode = random() > 0.5 ? 1 : -1;
}

function draw() {
	ellipse((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 20, 20);
	background(color(`hsb(${hue}, 60%, 70%)`));
	orbitControl();
	translate(0, -150);
	noStroke();
	directionalLight(color(`hsb(${(hue - mode * 120 + 360) % 360}, 40%, 100%)`), 0.5, 1.0, -1.0);
	ambientLight(100);

	push();
	rotateX(0.3);
	rotateZ(0.5);

	push();
	rotateY(frameCount * speed);
	translate(0, canvasSize * 0.02 * (-1.0 + sin(frameCount * speed * TWO_PI * 2)), 0);

	fill(color(`hsb(${(hue + mode * 120 + 360) % 360}, 80%, 80%)`));
	push();
	translate(0, - canvasSize * 0.20, 0);
	rotateZ(PI);
	cone(canvasSize * 0.12, canvasSize * 0.16);
	pop();

	fill(255);
	cylinder(canvasSize * 0.12, canvasSize * 0.24);

	fill(60);
	push();
	translate(0, canvasSize * 0.06, 0);
	rotateZ(PI);
	cone(canvasSize * 0.10, canvasSize * 0.24);
	pop();

	fill(color(`hsb(${(hue + mode * 120 + 360) % 360}, 80%, 80%)`));
	for (let i = 0; i < 4; i++) {
		push();
		rotateY(TWO_PI * i / 4);
		translate(canvasSize * 0.12, canvasSize * 0.05, 0);
		rotateZ(-0.2);
		box(canvasSize * 0.08, canvasSize * 0.16, canvasSize * 0.01);
		pop();
	}

	pop();

	fill(255,150);
	for (let i = 0; i < N; i++) {
		push();
		rotateY(smokes[i].angle);
		translate(smokes[i].r * canvasSize * 0.1 * (1.0 - 0.5 * cos(smokes[i].life * PI)), map(smokes[i].life, 0, 1, canvasSize * 0.18, canvasSize * 0.5), 0);
		sphere(canvasSize * 0.05 * sin(smokes[i].life * PI));
		smokes[i].life += speed;
		if (smokes[i].life > 1.0) {
			smokes[i].r = random();
			smokes[i].angle = random(TWO_PI);
			smokes[i].life = 0.0;
		}
		pop();
	}

	pop();
}

